import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { ApiService } from '../api.service';

@Component({
  selector: 'app-strategy-builder',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
    <div class="container">
      <div class="card">
        <h1>Strategy Builder</h1>

        <div *ngIf="message" class="alert" [class.alert-success]="!error" [class.alert-danger]="error">
          {{ message }}
        </div>

        <form (ngSubmit)="onSave()">
          <div class="form-group">
            <label>Stock Symbol:</label>
            <input type="text" class="form-control" [(ngModel)]="strategy.stock" name="stock" placeholder="e.g., AAPL">
          </div>

          <div class="form-group">
            <label>Expected Profit ($):</label>
            <input type="number" class="form-control" [(ngModel)]="strategy.expectedProfit" name="expectedProfit" step="0.01">
          </div>

          <div class="form-group">
            <label>Expected Loss ($):</label>
            <input type="number" class="form-control" [(ngModel)]="strategy.expectedLoss" name="expectedLoss" step="0.01">
          </div>

          <div class="form-group">
            <label>Notes:</label>
            <textarea class="form-control" [(ngModel)]="strategy.notes" name="notes" rows="4" placeholder="Strategy description and notes"></textarea>
          </div>

          <div style="display: flex; gap: 10px;">
            <button type="submit" class="btn" [disabled]="loading">
              {{ loading ? 'Saving...' : 'Save Strategy' }}
            </button>
            <button type="button" class="btn btn-secondary" (click)="goBack()">Back to Dashboard</button>
          </div>
        </form>

      </div>
    </div>
  `
})
export class StrategyBuilderComponent {
  strategy = {
    stock: '',
    expectedProfit: null,
    expectedLoss: null,
    notes: ''
  };
  loading = false;
  message = '';
  error = false;

  constructor(private apiService: ApiService, private router: Router) {}

  onSave() {
    this.loading = true;
    this.message = '';

    const strategyData = {
      expected_profit: this.strategy.expectedProfit,
      expected_loss: this.strategy.expectedLoss,
      notes: this.strategy.notes
    };

    this.apiService.createStrategy(strategyData).subscribe({
      next: (response) => {
        this.message = 'Strategy saved successfully!';
        this.error = false;
        this.loading = false;
        setTimeout(() => this.router.navigate(['/dashboard']), 2000);
      },
      error: (error) => {
        this.message = 'Failed to save strategy';
        this.error = true;
        this.loading = false;
      }
    });
  }

  goBack() {
    this.router.navigate(['/dashboard']);
  }
}
